/** Find a single repair line item by ID. */
async function repoFindLineItemById(id: string): Promise<typeof repairLineItems.$inferSelect | undefined> {
  const [result] = await db
    .select()
    .from(repairLineItems)
    .where(eq(repairLineItems.id, id))

  return result ?? undefined
}

/** Find all line items for a repair. */
async function repoFindLineItemsByRepairId(repairId: string): Promise<typeof repairLineItems.$inferSelect[]> {
  return db
    .select()
    .from(repairLineItems)
    .where(eq(repairLineItems.repairId, repairId))
    .orderBy(asc(repairLineItems.createdAt))
}

/** Find all work logs for a repair. */
async function repoFindWorkLogsByRepairId(repairId: string): Promise<typeof workLogs.$inferSelect[]> {
  return db
    .select()
    .from(workLogs)
    .where(eq(workLogs.repairId, repairId))
    .orderBy(asc(workLogs.startedAt))
}

/** Find all active labor services, optionally filtered by billing type. */
/** Labor service shape returned by raw SQL queries (camelCase) */
type LaborServiceRow = {
  id: string
  name: string
  description: string | null
  billingType: 'hourly' | 'fixed'
  defaultRate: number
  isActive: boolean
}

async function repoFindLaborServices(billingType?: 'hourly' | 'fixed'): Promise<LaborServiceRow[]> {
  const whereClause = billingType
    ? `WHERE is_active = 1 AND billing_type = ?`
    : `WHERE is_active = 1`

  const client = sqliteDb as Database.Database
  const rows = client.prepare(
    `SELECT id, name, description, billing_type, default_rate, is_active FROM labor_services ${whereClause} ORDER BY name`
  ).all(billingType ? [billingType] : []) as Array<{
    id: string
    name: string
    description: string | null
    billing_type: 'hourly' | 'fixed'
    default_rate: number
    is_active: number
  }>

  return rows.map((row) => ({
    id: row.id,
    name: row.name,
    description: row.description,
    billingType: row.billing_type as 'hourly' | 'fixed',
    defaultRate: Number(row.default_rate),
    isActive: Boolean(row.is_active),
  }))
}

/** Find all VAT rates. */
async function repoFindAllVatRates(): Promise<Map<string, number>> {
  const rows = await db.select({ id: vatRates.id, rate: vatRates.rate }).from(vatRates)
  const map = new Map<string, number>()
  for (const row of rows) {
    map.set(row.id, Number(row.rate))
  }
  return map
}

// ============================================================================
// Helpers — compute line totals using shared pricing lib
// ============================================================================

/** Compute line item totals: net, vat, gross from unit price, quantity, discount, and VAT rate. */
function computeLineTotals(
  unitPriceNet: number,
  quantity: number,
  discountPercentBps: number | null | undefined,
  vatRateBps: number
): { net: number; vat: number; gross: number } {
  const discountFactor = discountPercentBps ? 1 - discountPercentBps / 10000 : 1
  const discountedNetPerUnit = Math.round(unitPriceNet * discountFactor)
  const lineNetTotal = discountedNetPerUnit * quantity
  const lineVatTotal = Math.round(lineNetTotal * vatRateBps / 10000)
  return { net: lineNetTotal, vat: lineVatTotal, gross: lineNetTotal + lineVatTotal }
}

