describe('transitionRepairStatus', () => {
  let repairId: string

  beforeEach(async () => {
    // Clean up
    await db.delete(repairStatusHistory)
    await db.delete(repairs)
    await db.delete(bicycles)
    await db.delete(customers)

    // Create a test customer and bicycle for the repair
    const customer = await createTestCustomer()
    const bicycle = await createTestBicycle(customer.id)
    repairId = await createTestRepair(bicycle.id)
  })

  it('transitions from intake to in_progress', async () => {
    const result = await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })

    expect(result.status).toBe('in_progress')

    // Verify status history was recorded
    const [history] = await db
      .select()
      .from(repairStatusHistory)
      .where(eq(repairStatusHistory.repairId, repairId))
      .orderBy(desc(repairStatusHistory.transitionedAt))

    expect(history.status).toBe('in_progress')
  })

  it('transitions from in_progress to on_hold with hold reason', async () => {
    // First transition to in_progress
    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })

    const result = await transitionRepairStatus(repairId, {
      targetStatus: 'on_hold',
      holdReason: 'waiting_parts',
      holdReasonNote: 'Waiting for brake pads from supplier',
    })

    expect(result.status).toBe('on_hold')
    expect(result.holdReason).toBe('waiting_parts')
    expect(result.holdReasonNote).toBe('Waiting for brake pads from supplier')
  })

  it('transitions from on_hold back to in_progress', async () => {
    // First transition to in_progress, then on_hold
    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })
    await transitionRepairStatus(repairId, {
      targetStatus: 'on_hold',
      holdReason: 'other',
      holdReasonNote: 'On hold',
    })

    const result = await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })

    expect(result.status).toBe('in_progress')
  })

  it('transitions from in_progress to verified', async () => {
    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })

    const result = await transitionRepairStatus(repairId, { targetStatus: 'verified' })

    expect(result.status).toBe('verified')
  })

  it('transitions from verified to ready', async () => {
    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })
    await transitionRepairStatus(repairId, { targetStatus: 'verified' })

    const result = await transitionRepairStatus(repairId, { targetStatus: 'ready' })

    expect(result.status).toBe('ready')
  })

  it('transitions from ready to completed', async () => {
    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })
    await transitionRepairStatus(repairId, { targetStatus: 'verified' })
    await transitionRepairStatus(repairId, { targetStatus: 'ready' })

    const result = await transitionRepairStatus(repairId, { targetStatus: 'completed' })

    expect(result.status).toBe('completed')
  })

  it('transitions from any status to cancelled', async () => {
    // Transition to in_progress first
    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })

    const result = await transitionRepairStatus(repairId, { targetStatus: 'cancelled' })

    expect(result.status).toBe('cancelled')
  })

  it('rejects invalid status transition (intake → ready)', async () => {
    await expect(transitionRepairStatus(repairId, { targetStatus: 'ready' }))
      .rejects.toThrow()
  })

  it('rejects transition from completed to any other status', async () => {
    // Complete the repair first
    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })
    await transitionRepairStatus(repairId, { targetStatus: 'verified' })
    await transitionRepairStatus(repairId, { targetStatus: 'ready' })
    await transitionRepairStatus(repairId, { targetStatus: 'completed' })

    // Try to transition from completed (should fail)
    await expect(transitionRepairStatus(repairId, { targetStatus: 'in_progress' }))
      .rejects.toThrow()
  })

  it('requires holdReasonNote when setting holdReason', async () => {
    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })

    // Missing holdReasonNote should fail
    await expect(transitionRepairStatus(repairId, {
      targetStatus: 'on_hold',
      holdReason: 'waiting_parts',
      // no holdReasonNote — should fail
    })).rejects.toThrow()
  })
})

