    run(
      'INSERT INTO customers (id, type, first_name, last_name, company_name, vat_id, phone, email, street, number, bus, postal_code, city, country, notification_preference) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
      [id2, 'private', 'John', 'Smith', null, null, '+32480123456', 'john@example.com', null, null, null, null, null, 'BE', null]
    )
    const id3 = crypto.randomUUID()
    const now = Date.now()
    run(
      'INSERT INTO bicycles (id, source, template_id, customer_id, brand, model, year, color, frame_size, status, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
      [id3, 'customer_owned', null, id2, 'Specialized', 'Tarmac', 2024, 'Red', 'M', 'inventory', now]
    )

    // Create test repairs with different statuses and dates
    const futureDate = Date.now() + 86400000 * 3 // 3 days from now
    const pastDate = Date.now() - 86400000 * 2 // 2 days ago

    repairIds.push(await createTestRepairWithDates(bicycle1.id, 'intake', null, futureDate))
    repairIds.push(await createTestRepairWithDates(bicycle1.id, 'in_progress', null, pastDate))
    repairIds.push(await createTestRepairWithDates(bicycle2.id, 'on_hold', null, futureDate))
    repairIds.push(await createTestRepairWithDates(bicycle2.id, 'verified', null, pastDate))
  })

  it('returns all repairs when no filters applied', async () => {
    const result = await getRepairsList({}, 1, 20)

    expect(result.total).toBe(4)
    expect(result.repairs.length).toBe(4)
    expect(result.page).toBe(1)
    expect(result.pageSize).toBe(20)
    expect(result.totalPages).toBe(1)
  })

  it('returns repairs enriched with customer name and bicycle info', async () => {
    const result = await getRepairsList({}, 1, 20)

    // All repairs should have customerName (Jane Doe) since they're linked to customer1's bicycles
    expect(result.repairs[0].customerName).toBe('Jane Doe')
    expect(result.repairs[0].bicycleBrand).toBeDefined()
    expect(result.repairs[0].bicycleModel).toBeDefined()
  })

  it('sorts by planned_date descending (most urgent first)', async () => {
    const result = await getRepairsList({}, 1, 20)

    // Future dates should come before past dates
    expect(result.repairs[0].plannedDate).toBeGreaterThan(result.repairs[result.repairs.length - 1].plannedDate!)
  })

  it('filters by status', async () => {
    const result = await getRepairsList({ status: 'intake' }, 1, 20)

    expect(result.total).toBe(1)
    expect(result.repairs[0].status).toBe('intake')
  })

  it('filters by assignedTo (unassigned)', async () => {
    // All test repairs are unassigned
    const result = await getRepairsList({ assignedTo: null }, 1, 20)

    expect(result.total).toBe(4)
  })

  it('paginates results correctly', async () => {
    const page1 = await getRepairsList({}, 1, 2)
    const page2 = await getRepairsList({}, 2, 2)

    expect(page1.repairs.length).toBe(2)
    expect(page2.repairs.length).toBe(2)
    expect(page1.total).toBe(4)
    expect(page1.totalPages).toBe(2)
    expect(page2.page).toBe(2)
  })

  it('filters by pickup date today', async () => {
    const result = await getRepairsList({ pickupDateFilter: 'today' }, 1, 20)

    // None of our test repairs have pickup dates set to today
    expect(result.repairs.length).toBe(0)
  })

  it('filters by date range (from/to) using plannedDate', async () => {
    const futureDate = Date.now() + 86400000 * 3 // 3 days from now
    const result = await getRepairsList({ from: futureDate - 1000, to: futureDate + 1000 }, 1, 20)

    // Only repairs with plannedDate in the narrow range around futureDate should match
    expect(result.total).toBe(2) // intake and on_hold both have futureDate
    for (const repair of result.repairs) {
      expect(repair.plannedDate).toBeGreaterThanOrEqual(futureDate - 1000)
      expect(repair.plannedDate).toBeLessThanOrEqual(futureDate + 1000)
    }
  })

  it('falls back to createdAt when plannedDate is null for date range', async () => {
    // Create a repair with no plannedDate (null) — should use createdAt
    const customer = await createTestCustomer()
    const bicycle = await createTestBicycle(customer.id)
    const now = Date.now()
    const id = crypto.randomUUID()
    run(
      'INSERT INTO repairs (id, bicycle_id, assigned_to, status, customer_notes, internal_notes, hold_reason, hold_reason_note, planned_date, pickup_date, completed_at, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
      [id, bicycle.id, null, 'in_progress', 'No planned date', null, null, null, null, null, null, now]
    )

    const result = await getRepairsList({ from: now - 1000, to: now + 1000 }, 1, 20)

    // Should include the repair with null plannedDate (falls back to createdAt=now)
    expect(result.repairs.some(r => r.id === id)).toBe(true)
  })

  it('filters by statusIn (comma-separated statuses)', async () => {
    const result = await getRepairsList({ statusIn: ['intake', 'on_hold'] }, 1, 20)

    expect(result.total).toBe(2) // intake + on_hold
    for (const repair of result.repairs) {
      expect(['intake', 'on_hold']).toContain(repair.status)
    }
  })

  it('combines date range and statusIn filters', async () => {
    const futureDate = Date.now() + 86400000 * 3 // 3 days from now
    const result = await getRepairsList(
      { from: futureDate - 1000, to: futureDate + 1000, statusIn: ['intake'] },
      1,
      20,
    )

    // Only intake repairs in the date range
    expect(result.total).toBe(1)
    expect(result.repairs[0].status).toBe('intake')
  })
})

