describe('createRepairIntake', () => {
  beforeEach(async () => {
    // Clean up any test data
    await db.delete(repairStatusHistory)
    await db.delete(repairs)
    await db.delete(bicycles)
    await db.delete(customers)
  })

  it('creates a repair with an existing customer and existing bicycle', async () => {
    // Arrange: create customer and bicycle first
    const customer = await createTestCustomer()
    const bicycle = await createTestBicycle(customer.id)

    // Act: submit intake with existing customer + existing bicycle
    const input = {
      customerMode: 'existing' as const,
      existingCustomerId: customer.id,
      bicycleMode: 'select_existing' as const,
      existingBicycleId: bicycle.id,
      customerNotes: 'Brake squeaking on left pad',
    }

    // Assert: repair created with correct data
    const result = await createRepairIntake(input)

    expect(result.id).toBeDefined()
    expect(result.bicycleId).toBe(bicycle.id)
    expect(result.assignedTo).toBeNull()
    expect(result.status).toBe('intake')
    expect(result.customerNotes).toBe('Brake squeaking on left pad')
    expect(result.internalNotes).toBeNull()
    expect(result.holdReason).toBeNull()

    // Verify status history was recorded
    const [history] = await db
      .select()
      .from(repairStatusHistory)
      .where(eq(repairStatusHistory.repairId, result.id))

    expect(history).toBeDefined()
    expect(history.status).toBe('intake')
  })

  it('creates a new customer inline during intake', async () => {
    // Act: submit intake with new customer (walk-in)
    const input = {
      customerMode: 'new' as const,
      newCustomer: {
        firstName: 'Walk',
        lastName: 'In',
        phone: '+32499887766',
        email: 'walkin@example.com',
      },
      bicycleMode: 'create_new' as const,
      newBicycle: {
        brand: 'Specialized',
        model: 'Camille',
        color: 'Red',
      },
      customerNotes: 'Customer brought bike for tune-up',
    }

    // Assert: repair created with inline-created customer and bicycle
    const result = await createRepairIntake(input)

    expect(result.id).toBeDefined()
    expect(result.status).toBe('intake')
    expect(result.customerNotes).toBe('Customer brought bike for tune-up')

    // Verify the new bicycle was persisted and linked to a customer
    const [bicycle] = await db
      .select()
      .from(bicycles)
      .where(eq(bicycles.id, result.bicycleId))

    expect(bicycle).toBeDefined()
    expect(bicycle.customerId).not.toBeNull()

    // Verify the new customer exists with correct data
    const [customer] = await db
      .select()
      .from(customers)
      .where(eq(customers.id, bicycle!.customerId!))

    expect(customer.firstName).toBe('Walk')
    expect(customer.lastName).toBe('In')
    expect(customer.phone).toBe('+32499887766')
  })

  it('creates a new bicycle inline during intake', async () => {
    // Arrange: create customer first (existing)
    const customer = await createTestCustomer()

    // Act: submit intake with existing customer + new bicycle
    const input = {
      customerMode: 'existing' as const,
      existingCustomerId: customer.id,
      bicycleMode: 'create_new' as const,
      newBicycle: {
        brand: 'Cannondale',
        model: 'SuperSix',
        color: 'Blue',
      },
      customerNotes: 'New owner, first service',
    }

    // Assert: repair created with inline-created bicycle linked to existing customer
    const result = await createRepairIntake(input)

    expect(result.id).toBeDefined()
    expect(result.status).toBe('intake')

    // Verify the new bicycle was persisted and linked to the customer
    const [bicycle] = await db
      .select()
      .from(bicycles)
      .where(eq(bicycles.id, result.bicycleId))

    expect(bicycle.brand).toBe('Cannondale')
    expect(bicycle.model).toBe('SuperSix')
    expect(bicycle.color).toBe('Blue')
    expect(bicycle.customerId).toBe(customer.id)
  })

  it('rejects intake with empty customer notes', async () => {
    const customer = await createTestCustomer()
    const bicycle = await createTestBicycle(customer.id)

    // Act: submit intake without customerNotes (should fail validation)
    const input = {
      customerMode: 'existing' as const,
      existingCustomerId: customer.id,
      bicycleMode: 'select_existing' as const,
      existingBicycleId: bicycle.id,
      customerNotes: '', // empty notes should be rejected
    }

    await expect(createRepairIntake(input)).rejects.toThrow()
  })

  it('rejects intake with missing new customer phone', async () => {
    // Act: submit intake without phone (required for inline customer creation)
    const input = {
      customerMode: 'new' as const,
      newCustomer: {
        firstName: 'Test',
        lastName: 'User',
        email: 'test@example.com',
        // phone is missing — should fail validation
      } as any,
      bicycleMode: 'create_new' as const,
      newBicycle: {
        brand: 'Trek',
        model: 'Marlin',
        color: 'Black',
      },
      customerNotes: 'Test intake',
    }

    await expect(createRepairIntake(input)).rejects.toThrow()
  })

  it('rejects intake with missing bicycle mode data', async () => {
    const customer = await createTestCustomer()

    // Act: submit intake selecting existing bicycle but no ID provided
    const input = {
      customerMode: 'existing' as const,
      existingCustomerId: customer.id,
      bicycleMode: 'select_existing' as const,
      // missing existingBicycleId — should fail validation
      customerNotes: 'Test',
    }

    await expect(createRepairIntake(input)).rejects.toThrow()
  })

  it('creates repair with assignedTo=NULL (deferred assignment)', async () => {
    const customer = await createTestCustomer()
    const bicycle = await createTestBicycle(customer.id)

    const input = {
      customerMode: 'existing' as const,
      existingCustomerId: customer.id,
      bicycleMode: 'select_existing' as const,
      existingBicycleId: bicycle.id,
      customerNotes: 'Initial intake',
    }

    const result = await createRepairIntake(input)

    expect(result.assignedTo).toBeNull()
  })
})

