    expect(result.lineType).toBe('part')
    expect(result.partId).toBe(partId)
    expect(result.description).toBe('Brake Pads (Standard)')
    expect(result.quantity).toBe(1)
    expect(result.unitPriceNet).toBe(2500)
  })

  it('creates a labor line item with minutesWorked', async () => {
    const result = await createRepairLineItem(repairId, {
      lineType: 'labor',
      laborServiceId,
      description: 'Tune-up (1.5 hours)',
      quantity: 1,
      unitPriceNet: 35000, // cents/hour
      vatRateId,
      minutesWorked: 90,
    })

    expect(result.id).toBeDefined()
    expect(result.lineType).toBe('labor')
    expect(result.laborServiceId).toBe(laborServiceId)
    expect(result.minutesWorked).toBe(90)
  })

  it('rejects line item for non-existent repair', async () => {
    await expect(createRepairLineItem('non-existent-id', {
      lineType: 'part' as any,
      partId,
      description: 'Test',
      quantity: 1,
      unitPriceNet: 100,
      vatRateId,
    })).rejects.toThrow()
  })

  it('rejects line item for completed repair', async () => {
    // Complete the repair first
    await transitionRepairStatus(repairId, { targetStatus: 'in_progress' })
    await transitionRepairStatus(repairId, { targetStatus: 'verified' })
    await transitionRepairStatus(repairId, { targetStatus: 'ready' })
    await transitionRepairStatus(repairId, { targetStatus: 'completed' })

    await expect(createRepairLineItem(repairId, {
      lineType: 'part',
      partId,
      description: 'Test',
      quantity: 1,
      unitPriceNet: 100,
      vatRateId,
    })).rejects.toThrow()
  })

  it('computes line totals correctly (net + vat = gross)', async () => {
    const result = await createRepairLineItem(repairId, {
      lineType: 'part',
      partId,
      description: 'Test Part',
      quantity: 2,
      unitPriceNet: 1000, // 10.00 EUR net per unit
      vatRateId,
    })

    // 2 × 1000 = 2000 net, 2000 × 21% = 420 vat, 2420 gross
    expect(result.lineTotalNet).toBe(2000)
    expect(result.lineTotalVat).toBe(420)
    expect(result.lineTotalGross).toBe(2420)
  })

  it('applies discount correctly', async () => {
    const result = await createRepairLineItem(repairId, {
      lineType: 'part',
      partId,
      description: 'Test Part with 10% discount',
      quantity: 1,
      unitPriceNet: 1000,
      vatRateId,
      discountPercent: 1000, // 10% in basis points
    })

    // 1000 × (1 - 1000/10000) = 900 net, 900 × 21% = 189 vat, 1089 gross
    expect(result.lineTotalNet).toBe(900)
    expect(result.lineTotalVat).toBe(189)
    expect(result.lineTotalGross).toBe(1089)
  })
})

